 private func performance(_ mib:Int)async throws{let f=try await fixture(bytes:mib*1024*1024,media:"video"),start=Date();try await f.engine.run(f.item.id);let maxChunk=await f.download.maxChunk;XCTAssertLessThanOrEqual(maxChunk,65536);try await assertState(f,.restored);var usage=rusage();getrusage(RUSAGE_SELF,&usage);print("ACL013 generated \(mib) MiB restore seconds \(Date().timeIntervalSince(start)); peak test RSS \(usage.ru_maxrss); max chunk \(maxChunk)")}
 func testBatchBoundsDownloadsAndSerializesPhotos()async throws{let f=try await fixture(concurrency:2);await f.download.configure(delay:100_000_000);await f.photos.configure(delay:30_000_000);var second=f.item.evidence;second=RestoreEvidence(id:UUID(),cloudVersionId:second.cloudVersionId,mediaType:second.mediaType,expectedSize:second.expectedSize,expectedSha256:second.expectedSha256);let api=MultiRestoreAPI();let engine=RestoreCoordinator(queue:f.queue,files:f.files,api:api,downloader:f.download,photos:f.photos,capacity:FakeCapacity(bytes:nil),concurrency:2);let other=RestoreItem(accountID:f.item.accountID,libraryID:f.item.libraryID,evidence:second);try await f.queue.enqueue(other);try await engine.activate(account:f.item.accountID,library:f.item.libraryID);await engine.runDue();let dp=await f.download.peak,sp=await f.photos.peak,saves=await f.photos.saves;XCTAssertEqual(dp,2);XCTAssertEqual(sp,1);XCTAssertEqual(saves,2)}
