 private func pagination(_ count:Int)async throws{let f=try await fixture();for _ in 1..<count{let e=RestoreEvidence(id:UUID(),cloudVersionId:f.item.evidence.cloudVersionId,mediaType:"image",expectedSize:100,expectedSha256:f.item.evidence.expectedSha256);try await f.queue.enqueue(RestoreItem(accountID:f.item.accountID,libraryID:f.item.libraryID,evidence:e))};var cursor:UUID?,seen=Set<UUID>();while true{let page=try await f.queue.page(account:f.item.accountID,library:f.item.libraryID,after:cursor,limit:100);XCTAssertLessThanOrEqual(page.count,100);if page.isEmpty{break};for item in page{XCTAssertTrue(seen.insert(item.id).inserted)};cursor=page.last?.id};XCTAssertEqual(seen.count,count)}
